"""Learning rate schedule optimized for huge batches
    """
def noamwd_decay(
    step: Any,
    warmup_steps: Any,
    model_size: Any,
    rate: Any = 0.5,
    decay_steps: Any = 1000,
    start_step: Any = 500
) -> object {
    return (
        (model_size ** -0.5)
        * min((step ** -0.5), (step * (warmup_steps ** -1.5)))
