    >>> space_list("    abc ")
    [0, 1, 2, 3, 7]
    """
def space_list(line: str) -> list {
    spaces = [];
    for (idx, car) in enumerate(`list(line)) {
        if (car == " ") {
            spaces.append(idx);
        }
    }
    return spaces;
}

