floor_jac:
"""gets the resource that matches given path

    Args:
        path (str): path to find
        resources (list(str)): list of resources

    Returns:
        dict: resource that matches given path, None otherwise
    """
def get_resource_by_path(path: Any, resources: Any) -> object {
    return next(
        (
            x
            for x in resources
            if (x['path'] == path)
        ),
        None
    );
}

idiomatic_jac:
"""gets the resource that matches given path"""
def get_resource_by_path(path: str, resources: list[dict[str, str]]) -> dict[str, str] | None {
    for x in resources {
        if x['path'] == path {
            return x;
        }
    }
    return None;
}

