"""Convert physical signal values to digital values for an EDF channel."""
def phys2dig(
    signal: int | float | list[float],
    dmin: int,
    dmax: int,
    pmin: float,
    pmax: float
) -> int | float | list[float] {
    m = (pmax - pmin) / (dmax - dmin);
    b = (pmax / m) - dmax;
    return (signal / m) - b;
}

